2	package org.springframework.samples.petclinic.rest.function.owner;
3	
4	import java.util.Locale;
5	import java.util.Map;
6	
7	/**
8	 * Canonical form for an owner address, applied whenever an owner is created. Trims and collapses
9	 * runs of whitespace to a single space, upper-cases, and expands common abbreviations
10	 * ({@code ST}&nbsp;&rarr;&nbsp;{@code STREET}, {@code RD}&nbsp;&rarr;&nbsp;{@code ROAD},
11	 * {@code AVE}&nbsp;&rarr;&nbsp;{@code AVENUE}) as whole words. A {@code null} or blank value
12	 * normalizes to the empty string. The result is idempotent, so an already-normalized address is
13	 * returned unchanged. This is the single source of truth every address comparison uses.
14	 */
15	public final class AddressNormalizer {
16	
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET",
19	            "RD", "ROAD",
20	            "AVE", "AVENUE");
21	
22	    private AddressNormalizer() {
23	    }
24	
25	    /** Normalize an address to its canonical stored/returned form. */
26	    public static String normalize(String value) {
27	        if (value == null) {
28	            return "";
29	        }
30	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
31	        if (collapsed.isEmpty()) {
32	            return "";
33	        }
34	        String[] tokens = collapsed.split(" ");
35	        StringBuilder sb = new StringBuilder(collapsed.length());
36	        for (int i = 0; i < tokens.length; i++) {
37	            if (i > 0) {
38	                sb.append(' ');
39	            }
40	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
41	        }
42	        return sb.toString();
43	    }
44	}
