98	import java.security.MessageDigest;
99	import java.security.NoSuchAlgorithmException;
100	import java.util.HashSet;
101	import java.util.Set;
102	
103	import net.officefloor.plugin.variable.Val;
104	import org.springframework.samples.petclinic.model.Owner;
105	import org.springframework.samples.petclinic.repository.OwnerRepository;
106	import org.springframework.samples.petclinic.rest.function.common.Localities;
107	
108	/**
109	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
110	 * region derived from the owner's postcode (falling back to the city table) and HASH8 is the first
111	 * eight upper-case hex characters of SHA-256 over the normalized telephone concatenated with the
112	 * last name (e.g. {@code NSW-1A2B3C4D}). There is no per-city sequence number. Runs after telephone
113	 * normalization so the hash is taken over the stored, normalized (E.164) telephone.
114	 *
115	 * <p>If the computed code collides with an existing owner's {@code customerCode}, {@code -<n>} is
116	 * appended with the smallest {@code n} of 2 or more that makes it unique, so distinct owners always
117	 * receive distinct customer codes. Runs before the owner is saved, so it is matched only against
118	 * owners already present.
119	 */
120	public class AssignCustomerCode {
121	
122	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
123	        String region = Localities.region(owner.getPostcode(), owner.getCity());
124	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
125	        String base = region + "-" + hash8;
126	
127	        Set<String> existing = new HashSet<>();
128	        for (Owner other : ownerRepository.findAll()) {
129	            existing.add(other.getCustomerCode());
130	        }
131	
132	        String code = base;
133	        for (int n = 2; existing.contains(code); n++) {
134	            code = base + "-" + n;
135	        }
136	        owner.setCustomerCode(code);
137	    }
138	
139	    /** First {@code length} upper-case hex characters of SHA-256({@code value}). */
140	    private static String shaHex(String value, int length) {
141	        return sha256hex(value).substring(0, length).toUpperCase();
142	    }
143	
144	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
145	    private static String sha256hex(String value) {
146	        try {
147	            byte[] digest = MessageDigest.getInstance("SHA-256")
148	                    .digest(value.getBytes(StandardCharsets.UTF_8));
149	            StringBuilder sb = new StringBuilder(digest.length * 2);
150	            for (byte b : digest) {
151	                sb.append(String.format("%02x", b));
152	            }
153	            return sb.toString();
154	        }
155	        catch (NoSuchAlgorithmException e) {
156	            throw new IllegalStateException("SHA-256 not available", e);
157	        }
158	    }
159	}
