183	    public void service(@Val Owner owner) {
184	        String lastName = normalizeName(owner.getLastName());
185	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
186	        owner.setHouseholdId(deriveHouseholdId(lastName, postcode));
187	    }
