189	    /** The first 12 hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. */
190	    private static String deriveHouseholdId(String lastName, String postcode) {
191	        try {
192	            byte[] digest = MessageDigest.getInstance("SHA-256")
193	                    .digest((lastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
194	            StringBuilder sb = new StringBuilder();
195	            for (int i = 0; i < 6; i++) {
196	                sb.append(String.format("%02x", digest[i]));
197	            }
198	            return sb.toString();
199	        }
200	        catch (NoSuchAlgorithmException e) {
201	            throw new IllegalStateException("SHA-256 unavailable", e);
202	        }
203	    }
