205	    /** Trim, collapse internal whitespace runs to a single space, and lower-case. */
206	    private static String normalizeName(String value) {
207	        if (value == null) {
208	            return "";
209	        }
210	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
211	    }
