294	
295	import java.util.Locale;
296	
297	import net.officefloor.plugin.variable.Val;
298	import org.springframework.samples.petclinic.model.Owner;
299	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
300	import org.springframework.samples.petclinic.repository.OwnerRepository;
301	
302	/**
303	 * Raises the soft-match {@code possibleDuplicate} flag. A create request that is not a hard
304	 * duplicate (see {@link CheckOwnerIdentityUnique}) can still resemble an existing owner: when it
305	 * shares an existing owner's lastName (compared case-insensitively) and postcode but has a
306	 * <em>different</em> telephone, the new owner is created with {@code possibleDuplicate} true and
307	 * {@code possibleDuplicateOf} set to the matching owner's id. Otherwise {@code possibleDuplicate}
308	 * is false and {@code possibleDuplicateOf} absent.
309	 *
310	 * <p>Now that the household is keyed on (last name, postcode) — see {@link AssignHousehold} — that
311	 * soft-match key <em>is</em> the household key: a same lastName+postcode owner is only ever created
312	 * here as a <b>declared household member</b> (it reached this step because it set
313	 * {@code sharesHousehold}; without it {@link CheckOwnerIdentityUnique} would have rejected it as a
314	 * 409 household duplicate). A declared member is not a suspected duplicate, so an opted-in request
315	 * is never flagged.
316	 *
317	 * <p>Runs after {@link BuildOwner} (telephone, lastName and postcode are in their stored form) and
318	 * after {@link CheckOwnerIdentityUnique}, and before {@link SaveOwner} so the flag is compared only
319	 * against existing owners. When several existing owners match, the one with the lowest id wins for a
320	 * deterministic result.
321	 */
322	public class AssignPossibleDuplicate {
323	
324	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
325	        owner.setPossibleDuplicate(false);
326	        owner.setPossibleDuplicateOf(null);
327	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
328	            return; // a declared household member is not a suspected duplicate
329	        }
330	        String lastName = normalize(owner.getLastName());
331	        String postcode = normalize(owner.getPostcode());
332	        String telephone = normalize(owner.getTelephone());
333	        if (postcode.isEmpty()) {
334	            return; // no postcode to match on
335	        }
336	        Owner match = null;
337	        for (Owner existing : ownerRepository.findAll()) {
338	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
339	                continue; // never a duplicate of itself
340	            }
341	            if (lastName.equals(normalize(existing.getLastName()))
342	                    && postcode.equals(normalize(existing.getPostcode()))
343	                    && !telephone.equals(normalize(existing.getTelephone()))) {
344	                if (match == null || existing.getId() < match.getId()) {
345	                    match = existing;
346	                }
347	            }
348	        }
349	        if (match != null) {
350	            owner.setPossibleDuplicate(true);
351	            owner.setPossibleDuplicateOf(match.getId());
352	        }
353	    }
354	
355	    private static String normalize(String value) {
356	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
357	    }
358	}
