466	package org.springframework.samples.petclinic.rest.function.owner;
467	
468	import net.officefloor.plugin.variable.Val;
469	import org.springframework.samples.petclinic.model.Owner;
470	import org.springframework.samples.petclinic.repository.OwnerRepository;
471	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
472	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
473	
474	/**
475	 * The duplicate check, rejecting a create-owner request with a {@link DuplicateOwnerException} (409)
476	 * on either of two grounds:
477	 *
478	 * <ul>
479	 * <li><b>Full identity.</b> The whole derived {@link OwnerIdentityKey}
480	 * ({@code telephone|email|householdId}) equals an existing owner's. This always blocks, even when
481	 * the request opts in via {@code sharesHousehold}.</li>
482	 * <li><b>Household.</b> The computed {@code householdId} (see {@link AssignHousehold}, keyed on
483	 * last name and postcode) equals an existing owner's. Because the household is now keyed on
484	 * (last name, postcode), a second owner sharing those is the same household and is blocked — unless
485	 * the request sets {@code sharesHousehold}, which declares the new owner an intentional household
486	 * member and waves this ground through (the full-identity ground still applies).</li>
487	 * </ul>
488	 *
489	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} so the new owner's telephone, email
490	 * and {@code householdId} are all in their stored, computed form, and before {@link SaveOwner} so
491	 * the not-yet-persisted new owner is compared only against existing owners.
492	 */
493	public class CheckOwnerIdentityUnique {
494	
495	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
496	            throws DuplicateOwnerException {
497	        String identityKey = OwnerIdentityKey.of(owner);
498	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
499	        String householdId = owner.getHouseholdId();
500	        for (Owner existing : ownerRepository.findAll()) {
501	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
502	                continue; // never a duplicate of itself
503	            }
504	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
505	                throw new DuplicateOwnerException(identityKey);
506	            }
507	            if (!sharesHousehold && householdId != null
508	                    && householdId.equals(existing.getHouseholdId())) {
509	                throw new DuplicateOwnerException("household " + householdId);
510	            }
511	        }
512	    }
