515	package org.springframework.samples.petclinic.rest.function.owner;
516	
517	/**
518	 * The derived {@code checkDigit} for an owner: a single Luhn check digit (0-9) computed over the
519	 * digits contained in the owner's {@code customerCode}.
520	 *
521	 * <p>Non-digit characters (the dash and letters in {@code <REGION>-<HASH8>}) are ignored. The digits are
522	 * processed right-to-left, doubling every second digit starting with the rightmost and subtracting 9
523	 * from any doubled value above 9; the check digit is {@code (10 - (sum % 10)) % 10}.
524	 */
525	public final class CustomerCodeCheckDigit {
526	
527	    private CustomerCodeCheckDigit() {
528	    }
529	
530	    /** The Luhn check digit over the digits contained in {@code customerCode} (0 when null). */
531	    public static int of(String customerCode) {
532	        if (customerCode == null) {
533	            return 0;
534	        }
535	        int sum = 0;
536	        boolean dbl = true;
537	        for (int i = customerCode.length() - 1; i >= 0; i--) {
538	            char c = customerCode.charAt(i);
539	            if (c < '0' || c > '9') {
540	                continue;
541	            }
542	            int d = c - '0';
543	            if (dbl) {
544	                d *= 2;
545	                if (d > 9) {
546	                    d -= 9;
547	                }
548	            }
549	            sum += d;
550	            dbl = !dbl;
551	        }
552	        return (10 - (sum % 10)) % 10;
553	    }
554	}
