758	/**
759	 * The single derived identity used for owner duplicate detection.
760	 *
761	 * <p>An owner's {@code identityKey} is {@code normalizedTelephone + '|' + (email or empty) + '|' +
762	 * (householdId or empty)}, computed from the owner's already-normalized stored fields: the E.164
763	 * telephone (see {@link NormalizeOwnerTelephone}), the lower-cased email (see
764	 * {@link NormalizeOwnerEmail}), and the {@code householdId} assigned by {@link AssignHousehold}.
765	 * Two owners are duplicates only when their <em>whole</em> keys are equal — consolidating what were
766	 * once separate telephone, email and household checks into this one comparison. Because the
767	 * telephone is part of the key, two members of one household (same {@code householdId}) with
768	 * different telephones have different keys and are both allowed.
769	 */
770	public final class OwnerIdentityKey {
771	
772	    private OwnerIdentityKey() {
773	    }
