776	    public static String of(Owner owner) {
777	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
778	        String email = (owner.getEmail() == null || owner.getEmail().isBlank()) ? "" : owner.getEmail();
779	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
780	        return telephone + "|" + email + "|" + householdId;
781	    }
