892	package org.springframework.samples.petclinic.rest.function.owner;
893	
894	/**
895	 * Converts raw telephone numbers into E.164 form ('+' followed by 8 to 15 digits). A leading '+'
896	 * and country code are kept when present, otherwise country code '+61' is assumed and a single
897	 * leading '0' is dropped from the national digits. Spaces, dashes and brackets are stripped.
898	 *
899	 * <p>Not a function class (never wired into a YAML pipeline) — just shared logic for
900	 * {@link NormalizeOwnerTelephone} and the identity key (see {@link OwnerIdentityKey}).
901	 */
902	public final class TelephoneE164 {
903	
904	    private TelephoneE164() {
905	    }
906	
907	    /**
908	     * Converts {@code telephone} into E.164, or returns {@code null} when it cannot form a valid
909	     * E.164 number.
910	     */
911	    public static String toE164(String telephone) {
912	        if (telephone == null) {
913	            return null;
914	        }
915	        // Strip spaces, dashes and brackets.
916	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
917	        String digits;
918	        if (cleaned.startsWith("+")) {
919	            // Keep the explicit country code; the remainder must be all digits.
920	            digits = cleaned.substring(1);
921	        }
922	        else {
923	            // Assume '+61' and drop a single leading '0' from the national digits.
924	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
925	            digits = "61" + national;
926	        }
927	        if (!digits.matches("\\d{8,15}")) {
928	            return null;
929	        }
930	        return "+" + digits;
931	    }
932	
933	    /**
934	     * Formats an E.164 number for humans as the country code, a space, then the national digits
935	     * grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678'). The country code is '+61'
936	     * or '+1' when recognised, otherwise a two-digit code is assumed. Expects {@code e164} already
937	     * in valid E.164 form (a '+' followed by 8 to 15 digits), as returned by {@link #toE164};
938	     * returns {@code null} for a {@code null} or non-E.164 value.
939	     */
940	    public static String toDisplay(String e164) {
941	        if (e164 == null || !e164.startsWith("+")) {
942	            return null;
943	        }
944	        String digits = e164.substring(1);
945	        if (!digits.matches("\\d{8,15}")) {
946	            return null;
947	        }
948	        String code;
949	        if (digits.startsWith("61")) {
950	            code = "61";
951	        }
952	        else if (digits.startsWith("1")) {
953	            code = "1";
954	        }
955	        else {
956	            // Unknown country code: assume a two-digit code.
957	            code = digits.substring(0, 2);
958	        }
959	        String national = digits.substring(code.length());
960	        StringBuilder grouped = new StringBuilder();
961	        for (int i = 0; i < national.length(); i += 3) {
962	            if (grouped.length() > 0) {
963	                grouped.append(' ');
964	            }
965	            grouped.append(national, i, Math.min(i + 3, national.length()));
966	        }
967	        return "+" + code + " " + grouped;
968	    }
969	
970	    /**
971	     * Checks the national-number length of an E.164 number against its country code: '+61'
972	     * requires 9 national digits and '+1' requires 10. Country codes without a per-country length
973	     * rule here pass (only the generic 8-to-15-digit bound applies to them). Expects {@code e164}
974	     * already in valid E.164 form (a '+' followed by 8 to 15 digits), as returned by
975	     * {@link #toE164}; a {@code null} or non-E.164 value fails.
976	     */
977	    public static boolean nationalLengthValid(String e164) {
978	        if (e164 == null || !e164.startsWith("+")) {
979	            return false;
980	        }
981	        String digits = e164.substring(1);
982	        // Longest known country code first: '+1' would also prefix-match, but '+61' never
983	        // starts with '1' and '+1' never starts with '61', so the two do not collide.
984	        if (digits.startsWith("61")) {
985	            return digits.length() - 2 == 9;
986	        }
987	        if (digits.startsWith("1")) {
988	            return digits.length() - 1 == 10;
989	        }
990	        return true;
991	    }
992	}
